+/** Picks a supported language from an Accept-Language header, or returns `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  if (!header) return fallback;
+  const raw = Array.isArray(header) ? header.join(",") : String(header);
+  const candidates = [];
+  for (const part of raw.split(",")) {
+    const [tagPart, ...params] = part.split(";").map((s) => s.trim());
+    if (!tagPart) continue;
+    const primary = tagPart.split("-")[0].toLowerCase();
+    if (!LANGUAGES.includes(primary)) continue;
+    let q = 1;
+    let valid = true;
+    for (const param of params) {
+      const m = /^q\s*=\s*(.+)$/i.exec(param);
+      if (m) {
+        const n = Number(m[1]);
+        if (!Number.isFinite(n) || n < 0 || n > 1) valid = false;
+        else q = n;
+      }
+    }
+    if (valid && q > 0) candidates.push({ lang: primary, q, index: candidates.length });
+  }
+  candidates.sort((a, b) => b.q - a.q || a.index - b.index);
+  return candidates[0]?.lang ?? fallback;
+}
